const PUBLIC_BASE_PATHS = new Set([...CORE_PATHS, ...SRD_2014_PATHS, ...SRD_2024_PATHS]);

export const CONTENT_PROFILES = Object.freeze({
  "public-base": Object.freeze({
    name: "public-base",
    isBundled: true,
    sourceCategories: LIVE_RELEASE_SOURCE_CATEGORIES,
    includes(relativePath) {
      return (
        relativePath === "system/system-proxies.xml" ||
        relativePath === "system/system-unarmed-riders.xml" ||
        PUBLIC_BASE_PATHS.has(relativePath)
      );
    },
  }),
  "reviewed-test": Object.freeze({
    name: "reviewed-test",
    isBundled: false,
    sourceCategories: Object.freeze([
      ...LIVE_RELEASE_SOURCE_CATEGORIES,
      "Dungeon Master’s Guide",
      "Monster Manual",
      "One Grung Above",
      "Xanathar’s Guide to Everything",
    ]),
    includes(relativePath) {
      return (
        (relativePath === "system/system-elements.xml" ||
          relativePath === "system/system-proxies.xml" ||
          relativePath === "system/system-unarmed-riders.xml") ||
        REVIEWED_TEST_PATHS.has(relativePath)
      );
    },
  }),
  full: Object.freeze({
    name: "full",
    isBundled: false,
    sourceCategories: Object.freeze([]),
    includes() {
      return true;
    },
  }),
});

export function resolveContentProfile(profile = "public-base") {
  const resolved = CONTENT_PROFILES[String(profile).trim()] ?? CONTENT_PROFILES["public-base"];
  return resolved;
}

export { CORE_PATHS, CORE_2014_TEST_PATHS, LIVE_RELEASE_SOURCE_CATEGORIES, PUBLIC_BASE_PATHS, REVIEWED_TEST_PATHS, SRD_2014_PATHS, SRD_2024_PATHS };
